package tn.esprit.partnerintelligence.entity;
import jakarta.persistence.*;import java.time.Instant;@Entity public class PartnerInsightSummary { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private Long partnerId; @Column(columnDefinition="TEXT") private String summary; private String language="en"; private Instant createdAt=Instant.now(); public Long getId(){return id;} public void setId(Long id){this.id=id;} public Long getPartnerId(){return partnerId;} public void setPartnerId(Long partnerId){this.partnerId=partnerId;} public String getSummary(){return summary;} public void setSummary(String summary){this.summary=summary;} public String getLanguage(){return language;} public void setLanguage(String language){this.language=language;} public Instant getCreatedAt(){return createdAt;} public void setCreatedAt(Instant createdAt){this.createdAt=createdAt;} }